const items = $input.all();
if (!items.length || !items[0].json.msg_id) return [];
return items.map(i => {
  const msg = typeof i.json.message === 'string' ? JSON.parse(i.json.message) : i.json.message;
  return { json: { ...i.json, ...msg } };
});

const allOrders = $('Load Canonical Order').all();
const allDims = $('Load dim_location').all();
const allTokens = $('Load LS Token').all();

return allOrders.map((orderItem, idx) => {
  const order = orderItem.json;
  const dim = allDims[idx].json;
  const customer = typeof order.customer === 'string' ? JSON.parse(order.customer) : order.customer;
  const extRef = order.external_ref;

  const email = `shop-${extRef}@frituuros.internal`;
  const nameParts = (customer.name || 'Guest').trim().split(/\s+/);
  const firstName = nameParts[0] || 'Guest';
  const lastName = nameParts.slice(1).join(' ') || '.';

  // LS POS delivery ticket renders deliveryStreet only (never deliveryStreetNumber),
  // so the full address line - house number included - must live in one field.
  const addr = customer.address || {};
  const fullLine = [addr.line1, addr.line2].filter(Boolean).join(' ').trim();

  return {
    json: {
      customer_payload: {
        email,
        firstName,
        lastName,
        telephone: customer.phone || '',
        companyId: Number(dim.lightspeed_company_id),
        city: addr.city || '',
        country: addr.country || '',
        street: fullLine,
        streetNumber: '',
        zip: addr.postal_code || '',
        deliveryStreet: fullLine,
        deliveryStreetNumber: '',
        deliveryZip: addr.postal_code || '',
        deliveryCity: addr.city || '',
        deliveryCountry: addr.country || ''
      },
      access_token: allTokens[idx].json.access_token,
      company_id: dim.lightspeed_company_id
    }
  };
});

const allOrders = $('Load Canonical Order').all();
const allDims = $('Load dim_location').all();
const allCustomerResps = $('POST /core/customer').all();
const allBuildCustomer = $('Build Customer Payload').all();
const allMsgs = $('Parse Messages').all();
const allCatalog = $('Load LS Catalog SKUs').all();

function centsToEur(c) { return Math.round(c) / 100; }
function eurToCents(e) { return Math.round(Number(e) * 100); }

// deliveryDate must be the promised delivery time, in the FUTURE. The POS only
// auto-processes/prints orders whose deliveryDate has not passed (Deliverect set
// promised time +15min; a past date leaves the order waiting for a manual print).
function computeDeliveryDate(order, dim) {
  const now = Date.now();
  const zone = (dim && dim.timezone) || 'Europe/Brussels';
  const fallback = () => new Date(now + 15 * 60 * 1000).toISOString();
  try {
    let DT = (typeof DateTime !== 'undefined') ? DateTime : null;
    if (!DT) { try { DT = require('luxon').DateTime; } catch (e) { DT = null; } }
    if (order.source === 'takeaway') {
      const est = order.order_type === 'delivery'
        ? (order.raw_est_delivery || order.raw_est_pickup)
        : (order.raw_est_pickup || order.raw_est_delivery);
      if (est) {
        const t = new Date(est);
        if (!isNaN(t.getTime()) && t.getTime() > now + 5 * 60 * 1000) return t.toISOString();
      }
      return fallback();
    }
    if (order.source === 'shopify') {
      let attrsRaw = order.raw_note_attributes;
      if (typeof attrsRaw === 'string') { try { attrsRaw = JSON.parse(attrsRaw); } catch (e) { attrsRaw = null; } }
      if (!Array.isArray(attrsRaw) || !DT) return fallback();
      const attrs = {};
      for (const a of attrsRaw) attrs[String(a.name || '').toLowerCase().trim()] = String(a.value || '');
      const timeStr = attrs['levertijd'] || attrs['delivery time'] || attrs['afhaaltijd'] || attrs['pickup time'] || '';
      const dateStr = attrs['leverdatum'] || attrs['delivery date'] || attrs['afhaaldatum'] || attrs['pickup date'] || '';
      const tm = timeStr.match(/(\d{1,2}):(\d{2})\s*(AM|PM)?/i);
      if (!tm) return fallback();
      let hh = parseInt(tm[1], 10);
      const mm = parseInt(tm[2], 10);
      const ap = (tm[3] || '').toUpperCase();
      if (ap === 'PM' && hh < 12) hh += 12;
      if (ap === 'AM' && hh === 12) hh = 0;
      let day = DT.now().setZone(zone);
      if (dateStr) {
        if (/^\d{4}-\d{2}-\d{2}T/.test(dateStr)) {
          const d = DT.fromISO(dateStr);
          if (d.isValid) day = d.setZone(zone);
        } else {
          const MONTHS = { januari: 1, februari: 2, maart: 3, april: 4, mei: 5, juni: 6, juli: 7, augustus: 8, september: 9, oktober: 10, november: 11, december: 12 };
          const dm = dateStr.toLowerCase().match(/(\d{1,2})\s+(januari|februari|maart|april|mei|juni|juli|augustus|september|oktober|november|december)\s+(\d{4})/);
          if (dm) day = DT.fromObject({ year: +dm[3], month: MONTHS[dm[2]], day: +dm[1] }, { zone });
        }
      }
      const slot = day.set({ hour: hh, minute: mm, second: 0, millisecond: 0 });
      if (slot.isValid && slot.toMillis() > now + 5 * 60 * 1000) return slot.toUTC().toISO();
      return fallback();
    }
  } catch (e) { /* fall through */ }
  return fallback();
}

// Build LS catalog Map<sku, priceCents> per location. Used to enforce price
// source-of-truth: LS catalog price wins when higher than Shopify (Joef rule -
// if LS=2.50 and Shopify=2.40, the Shopify price is stale; LS receipt must print
// the correct 2.50). orderPayments.amount stays = customer paid total.
const catalogPriceBySku = new Map();
for (const row of allCatalog) {
  const sku = row.json?.sku;
  const price = row.json?.price;
  if (sku && price != null) catalogPriceBySku.set(sku, eurToCents(price));
}

return allOrders.map((orderItem, idx) => {
  const order = orderItem.json;
  const dim = allDims[idx].json;
  const customerResponse = allCustomerResps[idx].json;
  const buildCustomer = allBuildCustomer[idx].json;
  const msg = allMsgs[idx].json;

  let customerId = 0;
  const respBody = customerResponse.body;
  if (typeof respBody === 'number' && respBody > 0) {
    customerId = respBody;
  } else if (respBody?.id) {
    customerId = respBody.id;
  } else if (customerResponse.data && typeof customerResponse.data === 'number') {
    customerId = customerResponse.data;
  }
  if (!customerId && order.ls_customer_id) {
    customerId = Number(order.ls_customer_id);
  }

  const items = typeof order.items === 'string' ? JSON.parse(order.items) : order.items;
  const payment = typeof order.payment === 'string' ? JSON.parse(order.payment) : order.payment;
  const lsTableIds = typeof dim.ls_table_ids === 'string' ? JSON.parse(dim.ls_table_ids) : (dim.ls_table_ids || {});
  const paymentTypeIds = typeof dim.payment_type_ids === 'string' ? JSON.parse(dim.payment_type_ids) : (dim.payment_type_ids || {});

  const orderType = order.order_type === 'delivery' ? 'delivery' : 'takeaway';
  const SROVA_VENDOR = 'via Srova Data';
  const channelLabel = order.source === 'shopify' ? 'SHOPIFY' : order.source === 'takeaway' ? 'TAKEAWAY' : String(order.source).toUpperCase();
  const orderTypeLabel = orderType === 'delivery' ? 'DELIVERY' : 'TAKEAWAY';
  const tableKey = `${order.source}_${order.order_type === 'delivery' ? 'delivery' : 'pickup'}`;
  const tableId = lsTableIds[tableKey] || 0;

  const channelKey = order.source === 'shopify' ? 'SHOPIFY API' : order.source === 'takeaway' ? 'TAKEAWAY_V2 API' : 'DELIVERECT API';
  const pt = paymentTypeIds[channelKey] || { id: 0, typeId: 0 };

  function payAtDoorWarning(p, totalEur) {
    if (p.status !== 'pending') return '';
    const labels = { cash: 'CASH', bancontact: 'BANCONTACT', voucher: 'BON', card_online: 'CASH/CARD' };
    const label = labels[p.method];
    return label ? ` | TE BETALEN: ${label} €${totalEur.toFixed(2)}` : '';
  }

  let customerObj = typeof order.customer === 'string' ? JSON.parse(order.customer) : order.customer;
  customerObj = customerObj || {};
  const customerNote = (customerObj.notes || '').trim();

  // Safety net: LS ticket templates vary - the address also goes into the order
  // note so it is always visible regardless of which fields the template prints.
  const addrO = customerObj.address || {};
  const addrFullLine = [
    [addrO.line1, addrO.line2].filter(Boolean).join(' ').trim(),
    [addrO.postal_code, addrO.city].filter(Boolean).join(' ').trim()
  ].filter(Boolean).join(', ');

  const itemNotes = (items || []).filter(it => it.notes).map(it => `- ${it.name}: ${it.notes}`).join('\n');

  const orderItems = items.map(item => {
    // Price source-of-truth: prefer LS catalog price when higher.
    // Compound SKUs already split at normalize: item.plu = base PLU.
    const shopifyCents = Number(item.unit_price_cents) || 0;
    const catalogCents = catalogPriceBySku.get(item.plu);
    const effectiveCents = (catalogCents != null && catalogCents > shopifyCents) ? catalogCents : shopifyCents;
    const unitPrice = centsToEur(effectiveCents);

    const mods = (item.modifiers || []).map(m => ({
      plu: m.plu, modifierId: 0, modifierValueId: 0,
      price: centsToEur(m.unit_price_cents),
      priceWithoutVat: centsToEur(m.unit_price_cents),
      description: m.name
    }));
    return {
      productPlu: item.plu, amount: item.qty, unitPrice,
      totalPrice: unitPrice * item.qty,
      unitPriceWithoutVat: unitPrice,
      totalPriceWithoutVat: unitPrice * item.qty,
      modifiers: mods
    };
  });

  // Delivery/service fee as a real LS line item (Deliverect pattern, PLU from
  // dim_location.delivery_plu — D14 Aalst/Berlare, F49 Dender). Without it the POS
  // sees items < paid (e.g. -€3.00 "te veel betaald") and refuses to auto-finalize/print.
  // Delta uses ORIGINAL prices (what the customer paid), independent of the
  // catalog-price-wins rule above.
  const originalItemsCents = (items || []).reduce((s, it) =>
    s + (Number(it.unit_price_cents) || 0) * (it.qty || 1)
      + (it.modifiers || []).reduce((ms, m) => ms + (Number(m.unit_price_cents) || 0), 0), 0);
  const feeCents = (Number(payment.total_cents) || 0) - originalItemsCents;
  if (feeCents > 0 && order.delivery_plu) {
    const feeEur = centsToEur(feeCents);
    orderItems.push({
      productPlu: order.delivery_plu, amount: 1,
      unitPrice: feeEur, totalPrice: feeEur,
      unitPriceWithoutVat: feeEur, totalPriceWithoutVat: feeEur,
      modifiers: []
    });
  }

  const payload = {
    type: orderType,
    description: `${channelLabel} · ${order.external_ref} · ${SROVA_VENDOR}`,
    companyId: Number(dim.lightspeed_company_id),
    customerId, tableId,
    deliveryDate: computeDeliveryDate(order, dim),
    externalReference: order.external_ref,
    note: [
      `*** ${channelLabel} · ${orderTypeLabel} ***`,
      `Ref: ${order.external_ref}${payAtDoorWarning(payment, centsToEur(payment.total_cents))}`,
      orderType === 'delivery' && addrFullLine ? `ADRES: ${addrFullLine}` : '',
      itemNotes,
      customerNote ? `KLANT: ${customerNote}` : '',
      `-- ${SROVA_VENDOR} --`
    ].filter(Boolean).join('\n'),
    status: 'ACCEPTED',
    orderItems,
    orderPayments: [{
      paymentTypeId: pt.id,
      paymentTypeTypeId: pt.typeId,
      amount: centsToEur(payment.total_cents),
      tip: 0
    }]
  };

  return {
    json: {
      payload,
      customerId,
      access_token: buildCustomer.access_token,
      canonical_id: order.id,
      external_ref: order.external_ref,
      location_key: order.location_key,
      correlation_id: order.correlation_id,
      msg_id: msg.msg_id
    }
  };
});

const resp = $('POST /establishmentorder').item.json;
const input = $('Build Order Payload').item.json;

const statusCode = resp.statusCode || resp.status || resp.error?.status || 0;
const body = resp.body ?? resp.data ?? resp;

const lsOrderId = (statusCode === 201 && typeof body === 'number') ? body : (body?.id ?? null);

let action, alert = false, validationError = null;

if (statusCode === 201 || statusCode === 200) {
  action = 'success';
} else if (statusCode === 409) {
  action = 'skip_success';
} else if (statusCode === 401) {
  action = 'retry';
} else if (statusCode === 400) {
  action = 'dlq';
  alert = true;
  validationError = resp.error?.message || body;
} else if (statusCode === 403) {
  action = 'dlq';
  alert = true;
} else if (statusCode >= 500 || statusCode === 429 || statusCode === 0) {
  action = 'retry';
} else {
  action = 'dlq';
  alert = true;
}

// SQL-safe error snippet for the DLQ insert (single quotes doubled, truncated)
const errorText = String(
  typeof validationError === 'object' && validationError !== null
    ? JSON.stringify(validationError)
    : (validationError ?? `HTTP ${statusCode}`)
).slice(0, 400).replace(/'/g, "''");

return [{
  json: {
    action,
    alert,
    validationError,
    error_text: errorText,
    lsOrderId,
    statusCode,
    canonical_id: input.canonical_id,
    external_ref: input.external_ref,
    location_key: input.location_key,
    correlation_id: input.correlation_id,
    customerId: input.customerId,
    msg_id: input.msg_id
  }
}];

