const httpResp = $('Check LS Existing').all();
const orders = $('Load Canonical Order').all();
const tokens = $('Load LS Token').all();
const msgs = $('Parse Messages').all();

return orders.map((orderItem, idx) => {
  const order = orderItem.json;
  const externalRef = order.external_ref;
  const resp = httpResp[idx]?.json;
  const tok = tokens[idx]?.json;
  const msg = msgs[idx]?.json;

  let lsOrders = [];
  if (Array.isArray(resp)) lsOrders = resp;
  else if (Array.isArray(resp?.body)) lsOrders = resp.body;
  else if (Array.isArray(resp?.data)) lsOrders = resp.data;

  const match = lsOrders.find(o => o && o.externalReference === externalRef);

  const baseOut = {
    canonical_id: order.id,
    external_ref: externalRef,
    location_key: order.location_key,
    correlation_id: order.correlation_id,
    msg_id: msg?.msg_id,
    access_token: tok?.access_token,
    ls_orders_returned: lsOrders.length
  };

  if (match && match.id) {
    return {
      json: {
        ...baseOut,
        idempotency_skip: true,
        existing_ls_order_id: String(match.id),
        existing_status: match.status
      }
    };
  }

  return {
    json: {
      ...baseOut,
      idempotency_skip: false
    }
  };
});

const skuRows = $input.all();
const orders = $('Load Canonical Order').all();
const msgs = $('Parse Messages').all();

const validSkus = new Set(skuRows.map(r => r.json.sku));

return orders.map((orderItem, idx) => {
  const order = orderItem.json;
  const msg = msgs[idx].json;
  const items = typeof order.items === 'string' ? JSON.parse(order.items) : order.items;

  const requiredPlus = new Set();
  for (const item of (items || [])) {
    if (item.plu) requiredPlus.add(item.plu);
    for (const mod of (item.modifiers || [])) {
      if (mod.plu) requiredPlus.add(mod.plu);
    }
  }

  const missing = [...requiredPlus].filter(plu => !validSkus.has(plu));

  return {
    json: {
      all_valid: missing.length === 0,
      missing_plus: missing,
      missing_plus_str: missing.join(', '),
      missing_plus_json: JSON.stringify(missing),
      required_count: requiredPlus.size,
      catalog_size: validSkus.size,
      canonical_id: order.id,
      external_ref: order.external_ref,
      source: order.source,
      location_key: order.location_key,
      correlation_id: order.correlation_id,
      msg_id: msg.msg_id,
    },
  };
});

